$bytes_afrisync_logo_full_1024_png = [Convert]::FromBase64String($afrisync_logo_full_1024_png)
$out_afrisync_logo_full_1024_png = Join-Path $assetsPath "afrisync_logo_full_1024.png"
[System.IO.File]::WriteAllBytes($out_afrisync_logo_full_1024_png, $bytes_afrisync_logo_full_1024_png)
