[System.IO.File]::WriteAllBytes($out_afrisync_logo_mark_512_png, $bytes_afrisync_logo_mark_512_png)
Write-Host "Created: $out_afrisync_logo_mark_512_png"

$hash_afrisync_logo_mark_512_png = (Get-FileHash -Algorithm SHA256 $out_afrisync_logo_mark_512_png).Hash.ToLower()
if ($hash_afrisync_logo_mark_512_png -ne "ee62b88c1b3b1951a2de5cc23966d9423373feefb245f74155d84bd93a736c8c") {
    throw "Checksum failed for afrisync_logo_mark_512.png"
}


Write-Host ""
Write-Host "AfriSync assets installed successfully."
Write-Host "Expected files:"
Write-Host " - $assetsPath\afrisync_logo_full_1024.png"
Write-Host " - $assetsPath\afrisync_logo_mark_512.png"
